// Index par pays + type de visa pour recherche rapide
export function findProcedure(country: string, visaType?: string): ProcedureInfo[] {
  const countryLower = country.toLowerCase();
  return procedureData.filter(p => {
    const matchCountry = p.country.toLowerCase().includes(countryLower) || countryLower.includes(p.country.toLowerCase());
    const matchType = !visaType || p.visaType.toLowerCase().includes(visaType.toLowerCase());
    return matchCountry && matchType;
  });
}





export function getByVisaType(type: string): ProcedureInfo[] {
  return procedureData.filter(p => p.visaType === type);
}export function getAllCountries(): string[] {
  const seen = new Set<string>();
  const result: string[] = [];
  for (const p of procedureData) {
    if (!seen.has(p.country)) { seen.add(p.country); result.push(p.country); }
  }
  return result.sort();
}
